// Package fixturekit is the runtime used by fixture factories generated by datlas.
//
// A Generator owns the random number generator, the fake data source and the clock
// of a factory, so that tests can make fixtures deterministic by fixing the seed and the clock.
// Generated factories expose their Generator through Faker() for ad-hoc values.
package fixturekit

import (
	"encoding/hex"
	"fmt"
	"math/rand/v2"
	"os"
	"strconv"
	"strings"
	"sync"
	"time"
)

// SeedEnv is the environment variable that sets the seed of generators created without WithSeed.
// Use it to reproduce a failing test with the seed reported by WithT.
const SeedEnv = "DATLAS_SEED"

// DefaultTimePrecision is the precision of generated times unless WithTimePrecision is used.
// Microseconds survive a round trip through most databases.
const DefaultTimePrecision = time.Microsecond

// Option configures a Generator.
type Option func(*config)

type config struct {
	seed      uint64
	hasSeed   bool
	clock     func() time.Time
	precision time.Duration
	t         TB
}

// TB is the subset of testing.TB used by WithT.
type TB interface {
	Helper()
	Cleanup(func())
	Failed() bool
	Logf(format string, args ...any)
}

// WithSeed makes the generated values deterministic.
// Two generators created with the same seed yield the same sequence of values
// as long as they are called in the same order.
func WithSeed(seed uint64) Option {
	return func(c *config) {
		c.seed = seed
		c.hasSeed = true
	}
}

// WithClock sets the clock used for time based values such as "now".
func WithClock(clock func() time.Time) Option {
	return func(c *config) {
		c.clock = clock
	}
}

// WithNow fixes the current time to t.
func WithNow(t time.Time) Option {
	return WithClock(func() time.Time { return t })
}

// WithTimePrecision truncates generated times to a multiple of d.
// Zero keeps the full precision of the clock. The default is DefaultTimePrecision.
// Generated times never carry a monotonic clock reading.
func WithTimePrecision(d time.Duration) Option {
	return func(c *config) {
		c.precision = d
	}
}

// WithT reports the seed of the generator through t when the test fails,
// so that the failure can be reproduced with SeedEnv.
func WithT(t TB) Option {
	return func(c *config) {
		c.t = t
	}
}

// Generator produces fake values. It is safe for concurrent use.
type Generator struct {
	mu        sync.Mutex
	seed      uint64
	rng       *rand.Rand
	clock     func() time.Time
	precision time.Duration
	seqs      map[string]int64
	seen      map[string]map[any]struct{}
	unique    int64
	// token is derived from the seed and makes unique values of different generators distinct.
	token string
}

// New returns a Generator configured by opts.
// Without WithSeed the seed is read from the SeedEnv environment variable, or chosen randomly.
// Without WithClock the generator uses time.Now.
// New panics if SeedEnv is set to an invalid value.
func New(opts ...Option) *Generator {
	c := config{clock: time.Now, precision: DefaultTimePrecision}
	for _, opt := range opts {
		opt(&c)
	}
	seed := c.seed
	if !c.hasSeed {
		if env := os.Getenv(SeedEnv); env != "" {
			v, err := strconv.ParseUint(env, 10, 64)
			if err != nil {
				panic(fmt.Sprintf("fixturekit: invalid %s=%q: %v", SeedEnv, env, err))
			}
			seed = v
		} else {
			seed = rand.Uint64()
		}
	}
	if c.t != nil {
		t := c.t
		t.Helper()
		t.Cleanup(func() {
			if t.Failed() {
				t.Logf("fixture seed: %d (rerun with %s=%d)", seed, SeedEnv, seed)
			}
		})
	}
	g := &Generator{
		seed:      seed,
		rng:       rand.New(rand.NewPCG(seed, seed^0x9e3779b97f4a7c15)),
		clock:     c.clock,
		precision: c.precision,
		seqs:      map[string]int64{},
		seen:      map[string]map[any]struct{}{},
	}
	g.token = g.chars(tokenChars, tokenLength)
	return g
}

const (
	tokenChars  = "abcdefghijklmnopqrstuvwxyz0123456789"
	tokenLength = 6
)

// Seed returns the seed of the generator.
func (g *Generator) Seed() uint64 {
	return g.seed
}

// Ptr returns a pointer to v.
func Ptr[T any](v T) *T {
	return &v
}

// Now returns the current time according to the generator's clock, truncated to its precision.
func (g *Generator) Now() time.Time {
	t := g.clock()
	if g.precision > 0 {
		return t.Truncate(g.precision)
	}
	return t.Round(0)
}

// Past returns a time within the year before Now, truncated to seconds.
func (g *Generator) Past() time.Time {
	d := time.Duration(g.Int64Range(1, int64(365*24*time.Hour/time.Second))) * time.Second
	return g.Now().Add(-d).Truncate(time.Second)
}

// Future returns a time within the year after Now, truncated to seconds.
func (g *Generator) Future() time.Time {
	d := time.Duration(g.Int64Range(1, int64(365*24*time.Hour/time.Second))) * time.Second
	return g.Now().Add(d).Truncate(time.Second)
}

// IntN returns a random int in [0, n).
func (g *Generator) IntN(n int) int {
	g.mu.Lock()
	defer g.mu.Unlock()
	return g.rng.IntN(n)
}

// Int64Range returns a random int64 in [lo, hi].
func (g *Generator) Int64Range(lo, hi int64) int64 {
	if lo > hi {
		panic(fmt.Sprintf("fixturekit: invalid range [%d, %d]", lo, hi))
	}
	g.mu.Lock()
	defer g.mu.Unlock()
	span := uint64(hi) - uint64(lo)
	if span == ^uint64(0) {
		return int64(g.rng.Uint64())
	}
	return lo + int64(g.rng.Uint64N(span+1))
}

// Uint64Range returns a random uint64 in [lo, hi].
func (g *Generator) Uint64Range(lo, hi uint64) uint64 {
	if lo > hi {
		panic(fmt.Sprintf("fixturekit: invalid range [%d, %d]", lo, hi))
	}
	g.mu.Lock()
	defer g.mu.Unlock()
	if lo == 0 && hi == ^uint64(0) {
		return g.rng.Uint64()
	}
	return lo + g.rng.Uint64N(hi-lo+1)
}

// Float64Range returns a random float64 in [lo, hi).
func (g *Generator) Float64Range(lo, hi float64) float64 {
	g.mu.Lock()
	defer g.mu.Unlock()
	return lo + g.rng.Float64()*(hi-lo)
}

// Bool returns a random bool.
func (g *Generator) Bool() bool {
	return g.IntN(2) == 1
}

// Seq returns the next value of the sequence named key, starting at 1.
func (g *Generator) Seq(key string) int64 {
	g.mu.Lock()
	defer g.mu.Unlock()
	g.seqs[key]++
	return g.seqs[key]
}

// UniqueAttempts is the number of values Unique draws before giving up.
const UniqueAttempts = 1000

// Unique returns a value of gen that g has not returned before for key.
// It draws again while gen returns a value already returned, and panics after UniqueAttempts
// draws, which happens when the values of gen are exhausted (e.g. a word list or a small range).
// Generated factories use the type and field as key, e.g. "example.com/app/model.Company.Name".
func Unique[T comparable](g *Generator, key string, gen func() T) T {
	for range UniqueAttempts {
		v := gen()
		g.mu.Lock()
		seen := g.seen[key]
		if seen == nil {
			seen = map[any]struct{}{}
			g.seen[key] = seen
		}
		_, dup := seen[v]
		if !dup {
			seen[v] = struct{}{}
		}
		g.mu.Unlock()
		if !dup {
			return v
		}
	}
	g.mu.Lock()
	n := len(g.seen[key])
	g.mu.Unlock()
	panic(fmt.Sprintf("fixturekit: no unique value for %s after %d attempts (%d values already generated); "+
		"its generator has run out of distinct values: widen it, or use seq", key, UniqueAttempts, n))
}

// nextUnique returns a number that is unique within the generator.
func (g *Generator) nextUnique() int64 {
	g.mu.Lock()
	defer g.mu.Unlock()
	g.unique++
	return g.unique
}

// UUID returns a random (version 4) UUID.
// Its type converts to any UUID type whose underlying type is [16]byte, such as github.com/google/uuid.UUID.
func (g *Generator) UUID() [16]byte {
	var u [16]byte
	g.mu.Lock()
	for i := 0; i < 16; i += 8 {
		v := g.rng.Uint64()
		for j := range 8 {
			u[i+j] = byte(v >> (8 * j))
		}
	}
	g.mu.Unlock()
	u[6] = (u[6] & 0x0f) | 0x40 // version 4
	u[8] = (u[8] & 0x3f) | 0x80 // RFC 4122 variant
	return u
}

// UUIDString returns a random (version 4) UUID in its canonical textual form.
func (g *Generator) UUIDString() string {
	u := g.UUID()
	var b [36]byte
	hex.Encode(b[0:8], u[0:4])
	b[8] = '-'
	hex.Encode(b[9:13], u[4:6])
	b[13] = '-'
	hex.Encode(b[14:18], u[6:8])
	b[18] = '-'
	hex.Encode(b[19:23], u[8:10])
	b[23] = '-'
	hex.Encode(b[24:], u[10:])
	return string(b[:])
}

func (g *Generator) pick(xs []string) string {
	return xs[g.IntN(len(xs))]
}

// FirstName returns a random first name.
func (g *Generator) FirstName() string { return g.pick(firstNames) }

// LastName returns a random last name.
func (g *Generator) LastName() string { return g.pick(lastNames) }

// Name returns a random full name.
func (g *Generator) Name() string { return g.FirstName() + " " + g.LastName() }

// Word returns a random word.
func (g *Generator) Word() string { return g.pick(words) }

// Sentence returns a random sentence.
func (g *Generator) Sentence() string {
	n := 4 + g.IntN(6)
	ws := make([]string, n)
	for i := range ws {
		ws[i] = g.Word()
	}
	s := strings.Join(ws, " ")
	return strings.ToUpper(s[:1]) + s[1:] + "."
}

// Username returns a random username such as "alice_k3x9q2_1".
// It is unique within the generator, and distinct from the usernames of generators with other seeds
// (a token derived from the seed is part of it), so tests using separate factories do not collide.
func (g *Generator) Username() string {
	return strings.ToLower(g.FirstName()) + "_" + g.token + "_" + strconv.FormatInt(g.nextUnique(), 10)
}

// Email returns a random e-mail address such as "alice.smith.k3x9q2.1@example.test".
// Like Username, it is unique within the generator and distinct across seeds.
// It always uses a domain reserved for testing (RFC 2606).
func (g *Generator) Email() string {
	local := strings.ToLower(g.FirstName() + "." + g.LastName())
	return local + "." + g.token + "." + strconv.FormatInt(g.nextUnique(), 10) + "@" + g.pick(domains)
}

// URL returns a random URL on a domain reserved for testing (RFC 2606).
func (g *Generator) URL() string {
	return "https://" + g.pick(domains) + "/" + g.Word() + "/" + g.Word()
}

// Phone returns a random phone number in the fictional 555-01xx range.
func (g *Generator) Phone() string {
	return fmt.Sprintf("+1-%03d-555-01%02d", g.Int64Range(200, 999), g.Int64Range(0, 99))
}

const (
	alphaChars    = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"
	alphaNumChars = alphaChars + "0123456789"
)

// Alpha returns a random string of n ASCII letters.
func (g *Generator) Alpha(n int) string { return g.chars(alphaChars, n) }

// AlphaNum returns a random string of n ASCII letters and digits.
func (g *Generator) AlphaNum(n int) string { return g.chars(alphaNumChars, n) }

func (g *Generator) chars(set string, n int) string {
	b := make([]byte, n)
	g.mu.Lock()
	defer g.mu.Unlock()
	for i := range b {
		b[i] = set[g.rng.IntN(len(set))]
	}
	return string(b)
}
